{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Camellianin B, a polyphenolic glycoside, was detected in rat brain after oral administration, directly demonstrating that glycosylated flavonoids can achieve CNS access despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cyanidin-3-O-glucoside was detected in rat brain after dietary or intravenous administration, showing direct brain penetration of an anthocyanin glucoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Cyanidin 3-glucoside was detected in human brain vascular endothelium and brain tissue, supporting translation of glycoside flavonoid CNS access to humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Intact cyanidin 3-galactoside was found in pig brain, providing large-animal confirmation that anthocyanin glycosides cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Chlorogenic acid, rutin, and hyperoside were detected in rat brain after oral administration, supporting brain access of polar polyphenol glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cyanidin-3-O-glucoside reached approximately 3.5 nmol/g in mouse brain after intraperitoneal injection, providing quantitative evidence of meaningful brain levels.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "After a blackberry anthocyanin-enriched diet, C3G was the predominant anthocyanin in rat brain and was higher in brain than plasma, indicating net brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar flavonoid C-glucoside, but multiple direct in vivo studies show that closely related flavonoid and anthocyanin glycosides are detected in brain across species and routes, including oral administration. The consistent supportive evidence outweighs physicochemical concerns, so meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct quantitative unbound brain-to-plasma ratio is available for the exact query C-glucoside; most evidence is qualitative detection.",
    "Potential efflux transporter interactions for the specific C-glucoside were not directly measured.",
    "C-glucoside versus O-glucoside metabolic stability may alter systemic exposure, but the direction of BBB access remains supported by the glycoside evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

